using UnityEngine;using UnityEngine.Rendering;using UnityEngine.SceneManagement;
// Persistent review-only scene settings. Never reasserts every frame.
[ExecuteAlways]public sealed class DenseRigifyStudioLighting:MonoBehaviour{
 public Cubemap studio;public float[] nativeDiffuseSH=new float[27];public bool applyOnEnable=true;
 bool owns;AmbientMode priorMode;SphericalHarmonicsL2 priorSH;Texture priorReflection;DefaultReflectionMode priorReflectionMode;float priorAmbientIntensity,priorReflectionIntensity;Material priorSky;Light priorSun;
 public void Apply(){if(!studio||nativeDiffuseSH==null||nativeDiffuseSH.Length!=27)throw new System.InvalidOperationException("Incomplete persistent studio");if(gameObject.scene!=SceneManager.GetActiveScene())return;if(!owns){priorMode=RenderSettings.ambientMode;priorSH=RenderSettings.ambientProbe;priorReflection=RenderSettings.customReflectionTexture;priorReflectionMode=RenderSettings.defaultReflectionMode;priorAmbientIntensity=RenderSettings.ambientIntensity;priorReflectionIntensity=RenderSettings.reflectionIntensity;priorSky=RenderSettings.skybox;priorSun=RenderSettings.sun;owns=true;}var sh=new SphericalHarmonicsL2();for(int ch=0;ch<3;ch++)for(int i=0;i<9;i++)sh[ch,i]=nativeDiffuseSH[ch*9+i];RenderSettings.ambientMode=AmbientMode.Custom;RenderSettings.ambientProbe=sh;RenderSettings.ambientIntensity=1;RenderSettings.defaultReflectionMode=DefaultReflectionMode.Custom;RenderSettings.customReflectionTexture=studio;RenderSettings.reflectionIntensity=1;RenderSettings.skybox=null;RenderSettings.sun=null;}
 public void Restore(){if(!owns)return;if(gameObject.scene==SceneManager.GetActiveScene()){bool ours=RenderSettings.customReflectionTexture==studio;if(ours){RenderSettings.customReflectionTexture=priorReflection;RenderSettings.defaultReflectionMode=priorReflectionMode;RenderSettings.reflectionIntensity=priorReflectionIntensity;}if(RenderSettings.ambientMode==AmbientMode.Custom){var current=RenderSettings.ambientProbe;bool same=true;for(int ch=0;ch<3;ch++)for(int i=0;i<9;i++)if(Mathf.Abs(current[ch,i]-nativeDiffuseSH[ch*9+i])>1e-6)same=false;if(same){RenderSettings.ambientProbe=priorSH;RenderSettings.ambientMode=priorMode;RenderSettings.ambientIntensity=priorAmbientIntensity;}}if(ours&&!RenderSettings.skybox)RenderSettings.skybox=priorSky;if(ours&&!RenderSettings.sun)RenderSettings.sun=priorSun;}owns=false;}
 void OnEnable(){if(applyOnEnable)Apply();}void OnDisable(){Restore();}void OnDestroy(){Restore();}
}
